# Session-only: this hook reports the Antigravity conversation so Amon can
# resume the pane. Lifecycle state comes from Amon's screen detection.

param([string]$Action = "")

# Antigravity CLI expects a JSON object on stdout and this hook never injects
# anything, so every exit path emits an empty object.
function Exit-Hook {
    Write-Output "{}"
    exit 0
}

if ($Action -ne "session") { Exit-Hook }
if ($env:AMON_ENV -ne "1") { Exit-Hook }
if ([string]::IsNullOrWhiteSpace($env:AMON_AGENT_ID)) { Exit-Hook }

$inputText = [Console]::In.ReadToEnd()
try {
    $payload = if ([string]::IsNullOrWhiteSpace($inputText)) { $null } else { $inputText | ConvertFrom-Json }
} catch {
    Exit-Hook
}

if ($null -eq $payload) { Exit-Hook }

$conversationId = if ($payload.conversationId -is [string]) { $payload.conversationId } else { $null }
if ([string]::IsNullOrWhiteSpace($conversationId)) { Exit-Hook }

$seq = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()
$amon = if ([string]::IsNullOrWhiteSpace($env:AMON_BIN_PATH)) { "amon" } else { $env:AMON_BIN_PATH }
try {
    $sessionArgs = @(
        "hook",
        "report-agent-session",
        $env:AMON_AGENT_ID,
        "--source",
        "amon:antigravity_cli",
        "--agent",
        "agy",
        "--seq",
        "$seq",
        "--agent-session-id",
        "$conversationId"
    )
    if ($payload.transcriptPath -is [string] -and -not [string]::IsNullOrWhiteSpace($payload.transcriptPath)) {
        $sessionArgs += @("--agent-session-path", "$($payload.transcriptPath)")
    }
    & $amon @sessionArgs 2>$null | Out-Null
} catch {
}

Exit-Hook
